import (
	context "context"
	fern "github.com/go-pagination-namespace-errors/fern"
	fernclient "github.com/go-pagination-namespace-errors/fern/client"
	option "github.com/go-pagination-namespace-errors/fern/option"
	users "github.com/go-pagination-namespace-errors/fern/users"
)

client := fernclient.NewClient(
	option.WithToken(
		"<YOUR_AUTH_TOKEN>",
	),
)
response, err := client.Users.List(
	context.TODO(),
	&users.ListUsersRequest{
		Cursor: fern.String(
			"abc",
		),
	},
)
